 "new_string": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find large monochromatic rectangles using histogram maximal-rectangle search.
    candidates = []
    for color in set(v for row in grid for v in row):
        heights = [0] * w
        for r in range(h):
            for c in range(w):
                heights[c] = heights[c] + 1 if grid[r][c] == color else 0
            stack = []
            for c in range(w + 1):
                cur = heights[c] if c < w else 0
                start = c
                while stack and stack[-1][1] > cur:
                    left, height = stack.pop()
                    width = c - left
                    if height >= 4 and width >= 5 and height * width >= 28:
                        candidates.append((height * width, r-height+1, left, r, c-1, color))
                    start = left
                if not stack or stack[-1][1] < cur:
                    stack.append((start, cur))
    # Largest rectangles first; each intended block is disjoint.
    occupied = set()
    for area, r0, c0, r1, c1, color in sorted(candidates, reverse=True):
        cells = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
        if cells & occupied:
            continue
        occupied |= cells
        for r,c in cells:
            out[r][c] = 4
    return out
